<script setup lang="ts">
import { computed,shallowRef,watch,useId,nextTick,useTemplateRef } from 'vue'
import { useRoute } from 'vue-router'
import { useWorkbench } from '@/hooks/useWorkbench'
import { stages,statuses,type WorkItem,type GroupBy,type Stage,type Status } from '@/services/workbench'
import { Button } from '@/components/ui/button'
import ModalDialog from '@/components/ModalDialog.vue'
import StatusBadge from '@/components/StatusBadge.vue'
import { useWorkActions } from '../hooks/useWorkActions'
const props=defineProps<{items:WorkItem[];groupBy:GroupBy;revision:number}>();const route=useRoute();const id=useId();const {snapshot}=useWorkbench()
const {move,confirm,cancel,open,blocker,error,notice,saving}=useWorkActions()
const board=useTemplateRef<HTMLElement>('board')
watch(notice,async value=>{if(value){await nextTick();if(document.activeElement===document.body)board.value?.focus()}})
const limits=defineModel<Record<string,number>>('limits',{required:true});const scrollLeft=defineModel<number>('scrollLeft',{required:true})
watch([board,scrollLeft],()=>{if(board.value)board.value.scrollLeft=scrollLeft.value},{flush:'post'})
const hideEmpty=shallowRef(false);const dragging=shallowRef<{item:WorkItem;revision:number;groupBy:GroupBy}>();const hovered=shallowRef('')
const labels=computed(()=>props.groupBy==='status'?statuses:stages)
const columns=computed(()=>Object.entries(labels.value).map(([key,label])=>({key,label,items:props.items.filter(i=>i[props.groupBy]===key)})).filter(c=>!hideEmpty.value||c.items.length))
watch([()=>props.items,()=>props.groupBy],()=>{dragging.value=undefined})
function start(event:DragEvent,item:WorkItem){if(!item.active||saving.value){event.preventDefault();return}dragging.value={item,revision:props.revision,groupBy:props.groupBy};if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',item.id)}}
async function drop(key:string){const current=dragging.value;dragging.value=undefined;hovered.value='';if(current&&current.groupBy===props.groupBy)await move(current.item,props.groupBy,key as Stage|Status,current.revision)}
function end(){dragging.value=undefined;hovered.value=''}
function taskCount(specId:string){const tasks=snapshot.value?.tasks.filter(t=>t.record.specId===specId&&t.record.active)??[];return tasks.filter(t=>t.record.status==='done').length+' / '+tasks.length+' 项任务完成'}
</script>
<template><div class="toolbar"><label class="check-label"><input v-model="hideEmpty" type="checkbox">隐藏空列</label><span class="muted">可拖动卡片，或用“移动到…”菜单；不改变列内排序。</span></div><p v-if="notice" role="status" class="notice">{{notice}}</p><p v-if="error&&!open" role="alert" class="notice error">{{error}}</p><div ref="board" tabindex="-1" class="board" @scroll.passive="scrollLeft=($event.target as HTMLElement).scrollLeft" :aria-label="groupBy==='status'?'按状态分组的看板':'按阶段分组的看板'"><section v-for="column in columns" :key="column.key" :class="['board-column',{'drop-target':hovered===column.key}]" :aria-label="column.label" @dragover.prevent="hovered=column.key" @dragleave="hovered=''" @drop.prevent="drop(column.key)"><header><h2>{{column.label}}</h2><span class="count">{{column.items.length}}</span></header><article v-for="item in column.items.slice(0,limits[column.key]??50)" :key="item.id" class="board-card" :draggable="item.active&&!saving" @dragstart="start($event,item)" @dragend="end"><span class="eyebrow">{{item.projectName}} · {{item.entity==='task'?'任务':'Spec'}}</span><RouterLink :to="{path:'/specs/'+item.specId,query:{taskId:item.entity==='task'?item.id:undefined,return:route.fullPath}}" class="board-title">{{item.title}}</RouterLink><p v-if="item.entity==='task'" class="muted">{{item.specTitle}}</p><div class="inline-meta"><StatusBadge :status="item.status" /><span>{{stages[item.stage]}}</span></div><p v-if="item.entity==='spec'" class="muted">{{taskCount(item.id)}}</p><p v-if="item.nextAction" class="card-next">{{item.nextAction}}</p><p v-if="item.status==='blocked'" class="blocker-text">{{item.blocker}}</p><p v-if="item.hasSourceProblem" class="warning-text">来源异常</p><p v-if="!item.active" class="muted">已停用，请到详情恢复</p><select :value="''" :aria-label="'移动 '+item.title+' 到其他'+(groupBy==='status'?'状态':'阶段')" :disabled="!item.active||saving" @change="move(item,groupBy,($event.target as HTMLSelectElement).value as Stage|Status,revision);($event.target as HTMLSelectElement).value=''"><option value="" disabled>移动到…</option><option v-for="(label,key) in labels" :key="key" :value="key" :disabled="item[groupBy]===key">{{label}}</option></select></article><Button v-if="column.items.length>(limits[column.key]??50)" variant="outline" @click="limits[column.key]=(limits[column.key]??50)+50">加载更多（{{column.items.length}}）</Button><p v-if="!column.items.length" class="column-empty">暂无工作项</p></section></div><ModalDialog v-model="open" title="记录阻塞原因" :busy="saving"><form class="form-stack" @submit.prevent="confirm"><label :for="id+'blocker'">阻塞说明（必填）</label><textarea :id="id+'blocker'" v-model="blocker" required rows="3" /><p v-if="error" role="alert" class="notice error">{{error}}</p><div class="form-actions"><Button variant="outline" type="button" :disabled="saving" @click="cancel">取消</Button><Button :disabled="saving">确认阻塞</Button></div></form></ModalDialog></template>
